ex-e15.code:
course = input('Course code: ').strip().upper()
raw_seats = input('Number of seats: ').strip()

is_comp_course = course.startswith('COMP')
has_whole_seats = raw_seats.isdigit()

if not is_comp_course or not has_whole_seats:
    print('Enter a COMP course and a whole seat count.')
else:
    seats = int(raw_seats)
    is_valid_count = 1 <= seats <= 40
    if is_valid_count:
        print('Request recorded:', course, seats)
    else:
        print('Seats must be from 1 to 40.')

